//! Exact token lists retain real inert HTML owner and promotion identity.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://inert-tokens.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn inert_html_class_list_exact_reads_mutations_attrs_and_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('span');owner.body.appendChild(source);source.className=' A\ud800z A�z A\ud800z ';var a=source.getAttributeNode('class'),list=source.classList,descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList');if(list!==source.classList||list!==descriptor.get.call(source)||!(list instanceof DOMTokenList)||Object.hasOwn(source,'classList')||list.length!==2||list[0]!=='A\ud800z'||list.item(1)!=='A�z'||list.item(2)!==null||list[2]!==undefined||!list.contains('A\ud800z')||list.contains('B\ud800z')||String(list)!==source.className)throw 'inert exact reads';var watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});list.add('B\udfffz');if(list.value!=='A\ud800z A�z B\udfffz'||a.value!==list.value||a!==source.getAttributeNode('class'))throw 'inert add';list.remove('A�z');if(list.value!=='A\ud800z B\udfffz')throw 'inert remove';if(!list.replace('A\ud800z','C\ud800z')||list.replace('absent','new')||list.value!=='C\ud800z B\udfffz')throw 'inert replace';if(!list.toggle('B\udfffz',true)||list.toggle('B\udfffz',false)||list.value!=='C\ud800z')throw 'inert toggle';source.classList='D\udfffz';if(list.value!=='D\udfffz')throw 'inert PutForwards';a.value='E\ud800z';if(list[0]!=='E\ud800z')throw 'inert live Attr';var records=watch.takeRecords();if(records.length!==6||records[0].oldValue!==' A\ud800z A�z A\ud800z '||records[5].oldValue!=='D\udfffz'||records[5].target!==source)throw 'inert records';var calls=0;list.add({toString:function(){calls++;source.className='fresh';return 'F\ud800z';}});if(calls!==1||list.value!=='fresh F\ud800z')throw 'read after conversion';var copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);if(copy===source||copy.classList===list||copy.classList.value!==list.value||!copy.classList.contains('F\ud800z')||copy.matches('.F�z')||source.ownerDocument!==owner)throw 'independent import';
"#);}
#[test]
fn inert_html_class_list_no_slot_handles_use_real_attributes_without_arena_aliases(){let(mut d,mut f,mut p)=fixture();let nodes=p.state.node_limit;let count=d.nodes.len();p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),other=owner.createElementNS('http://www.w3.org/1999/xhtml','div');source.className='A\ud800z';other.className='B\udfffz';var list=source.classList,otherList=other.classList,a=source.getAttributeNode('class');if(list===otherList||list!==source.classList||list.value!=='A\ud800z'||otherList.value!=='B\udfffz'||list.length!==1)throw 'no-slot identity';list.add('C\udfffz');other.classList='D\ud800z';if(list.value!=='A\ud800z C\udfffz'||otherList.value!=='D\ud800z'||a.value!==list.value)throw 'no-slot actual mutation';var count=0;list.forEach(function(value,index,current){if(current!==list||value!==list.item(index))throw 'forEach native';count++;});if(count!==2||Array.from(list).join('|')!=='A\ud800z|C\udfffz')throw 'no-slot iteration';
"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"var copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);if(copy.classList===list||copy.classList.value!==list.value||source.ownerDocument!==owner||copy.ownerDocument!==document)throw 'no-slot import';");}
#[test]
fn inert_html_class_list_saved_tokens_and_attr_survive_template_promotion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var t=document.createElement('template');t.innerHTML='<span class="seed seed">held</span>';var source=t.content.firstChild,list=source.classList,a=source.getAttributeNode('class'),owner=source.ownerDocument,watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});list.add('A\ud800z');var clone=t.cloneNode(true),other=clone.content.firstChild,otherList=other.classList;if(otherList===list||otherList.value!==list.value)throw 'cloned tokens';otherList.remove('seed');if(list.value!=='seed A\ud800z'||otherList.value!=='A\ud800z')throw 'independent cloned token state';document.getElementById('mount').appendChild(t.content);if(source.classList!==list||source.ownerDocument!==document||a!==source.getAttributeNode('class')||a.ownerDocument!==document||list.value!=='seed A\ud800z'||source.matches('.A�z'))throw 'promotion identity';list.replace('seed','B\udfffz');if(source.className!=='B\udfffz A\ud800z'||document.getElementsByClassName('B\udfffz')[0]!==source)throw 'promoted live backend';var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='seed seed'||records[1].oldValue!=='seed A\ud800z'||records[0].target!==source)throw 'promotion records';
"#);}
#[test]
fn inert_html_class_list_conversion_validation_empty_updates_and_abrupt_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('span'),list=source.classList,watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});list.add();list.remove();if(source.hasAttribute('class')||watch.takeRecords().length)throw 'absent empty update';list.value='';list.add();if(!source.hasAttribute('class')||watch.takeRecords().length!==2)throw 'present empty update';source.className='seed';watch.takeRecords();var order='',marker={};try{list.add({toString:function(){order+='a';return 'good';}},{toString:function(){order+='b';return 'bad token';}});throw 'invalid token accepted';}catch(e){if(e.name!=='InvalidCharacterError')throw e;}if(order!=='ab'||list.value!=='seed'||watch.takeRecords().length)throw 'all conversions before atomic validation';try{list.add({toString:function(){source.title='effect';throw marker;}});throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(list.value!=='seed'||source.title!=='effect')throw 'abrupt effects';var calls=0,add=DOMTokenList.prototype.add;try{add.call({}, {toString:function(){calls++;return 'bad';}});throw 'bad brand';}catch(e){if(!(e instanceof TypeError))throw e;}try{list.add(Symbol());throw 'Symbol accepted';}catch(e){if(!(e instanceof TypeError))throw e;}try{list.supports('anything');throw 'supports accepted';}catch(e){if(!(e instanceof TypeError))throw e;}if(calls||list.value!=='seed')throw 'brand and Symbol ordering';list.add('fresh');if(list.value!=='seed fresh')throw 'validation recovery';
"#);}
#[test]
fn inert_html_class_list_resource_and_cancellation_refusal_preserve_real_source_and_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('span');source.className='A\ud800z';var list=source.classList,a=source.getAttributeNode('class'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;
for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.limits.host.string_bytes=4};let e=p.runtime.execute(r#"list.add('longB\udfffz');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("limit"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;}
p.begin_job();run(&mut d,&mut f,&mut p,&format!("if(list.value!=='A\\ud800z'||a.value!==list.value||watch.takeRecords().length)throw 'refusal publication';var longValue='{}';source.className=longValue;watch.takeRecords();","x".repeat(5000)));let state=(p.state.retained,p.state.dom_commits);p.begin_job();p.state.execution_deadline=Some(Instant::now());let e=p.runtime.execute("list.add('fresh');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("time limit"),"{e}");assert_eq!((p.state.retained,p.state.dom_commits),state);p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.className!==longValue||a.value!==source.className||watch.takeRecords().length)throw 'cancelled publication';list.value='recovered';if(a.value!=='recovered'||watch.takeRecords().length!==1)throw 'fresh recovery';");}
#[test]
fn inert_html_class_list_scoped_snapshot_and_output_share_headroom_and_handles_remain_typed(){let(mut d,mut f,mut p)=fixture();let nodes=p.state.node_limit;p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','span');source.className='A\ud800z B\udfffz';var list=source.classList;"#);let value=p.runtime.execute("list;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();let Value::Host(list)=value else{panic!()};let retained=p.state.retained;let limit=p.state.retained_limit;let commits=p.state.dom_commits;let snapshot=2*size_of::<crate::dom_string::DomStringRef<'_>>();let output=DomString::from_units(&[65,0xd800,122],64).unwrap().capacity();
for(headroom,needle)in[(snapshot-1,"snapshot"),(snapshot+output-1,"output")]{p.begin_job();p.state.retained_limit=retained+headroom;let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap_err();assert!(error.contains(needle)&&error.contains("allowance"),"{error}");assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));}
p.begin_job();p.state.retained_limit=retained+snapshot+output;let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.class_list_get(list,"0").unwrap();assert!(matches!(value,Value::StringUnits(u)if u==[65,0xd800,122]));assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.node_limit=nodes;p.begin_job();
for handle in[0xc200_0000,0xc2ff_ffff,script_class_list::handle(script_inert_documents::ENTRY_END-1)]{let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(!bridge.class_list_receiver(handle));assert!(bridge.class_list_get(handle,"length").is_err());assert!(!bridge.named_map_receiver(handle));}
let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(bridge.class_list_receiver(list));assert!(!bridge.named_map_receiver(list));assert_eq!(bridge.class_list_keys(list).unwrap(),["0","1"]);assert_eq!(bridge.state.retained,retained);}

#[test]
fn inert_html_class_list_cannot_use_a_forged_sandbox_handle_to_mutate_classes(){let(mut d,mut f,mut p)=fixture();let value=p.runtime.execute("var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('span');source.className='seed';source;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();let Value::Host(owner)=value else{panic!()};assert!(node_index(owner).is_some());let retained=p.state.retained;let commits=p.state.dom_commits;let forged=script_class_list::sandbox_handle(owner);let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(bridge.inert_class_element_receiver(owner));assert!(!bridge.class_list_receiver(forged));assert!(bridge.class_list_set(forged,"value",Value::String("bad".into())).unwrap_err().contains("attribute"));assert_eq!((bridge.state.retained,bridge.state.dom_commits),(retained,commits));assert!(matches!(bridge.element_class_name_get(owner).unwrap(),Value::String(s)if s=="seed"));}
